package solution

import "testing"

func TestCountDigitInMultiplesIncludesZero(t *testing.T) {
	tests := []struct {
		limit   int
		divisor int
		digit   int
		want    int
	}{
		{1, 7, 0, 1},
		{11, 5, 0, 2},
		{11, 5, 5, 1},
		{13, 3, 1, 1},
		{12, 3, 1, 0},
	}
	for _, tc := range tests {
		got, err := CountDigitInMultiples(tc.limit, tc.divisor, tc.digit)
		if err != nil {
			t.Fatalf("CountDigitInMultiples(%d, %d, %d) returned error: %v", tc.limit, tc.divisor, tc.digit, err)
		}
		if got != tc.want {
			t.Errorf("CountDigitInMultiples(%d, %d, %d) = %d, want %d", tc.limit, tc.divisor, tc.digit, got, tc.want)
		}
	}
}

func TestCountDigitInMultiplesCountsRepeatedDigits(t *testing.T) {
	got, err := CountDigitInMultiples(112, 11, 1)
	if err != nil {
		t.Fatal(err)
	}
	// Multiples are 0, 11, 22, ..., 110. The digit 1 occurs twice in 11
	// and twice in 110.
	if got != 4 {
		t.Fatalf("count = %d, want 4", got)
	}
}

func TestCountDigitInMultiplesNonpositiveLimit(t *testing.T) {
	for _, limit := range []int{0, -1, -100} {
		got, err := CountDigitInMultiples(limit, 3, 0)
		if err != nil || got != 0 {
			t.Errorf("limit %d produced count %d, error %v", limit, got, err)
		}
	}
}

func TestCountDigitInMultiplesRejectsInvalidArguments(t *testing.T) {
	for _, divisor := range []int{0, -1} {
		if _, err := CountDigitInMultiples(10, divisor, 1); err == nil {
			t.Errorf("divisor %d was accepted", divisor)
		}
	}
	for _, digit := range []int{-1, 10} {
		if _, err := CountDigitInMultiples(10, 2, digit); err == nil {
			t.Errorf("digit %d was accepted", digit)
		}
	}
}

package solution

import (
    "strconv"
    "strings"
    "testing"
    "time"
)

func TestLargeDivisorTerminatesAfterTwoMultiples(t *testing.T) {
    if strconv.IntSize != 64 { t.Fatal("diagnostic requires the pinned 64-bit runtime") }
    divisor := int(1) << 62
    type result struct { count int; err error }
    done := make(chan result, 1)
    go func() {
        count, err := CountDigitInMultiples(divisor + 1, divisor, 0)
        done <- result{count, err}
    }()
    select {
    case got := <-done:
        want := 1 + strings.Count(strconv.Itoa(divisor), "0")
        if got.err != nil || got.count != want { t.Fatalf("got %v, want count %d", got, want) }
    case <-time.After(2 * time.Second):
        t.Fatal("two-multiple calculation did not terminate; signed increment wraps into a four-value cycle")
    }
}

