The following complete source counts occurrences of one decimal digit in the base-10 representations of all nonnegative multiples of `divisor` in the half-open interval `[0, limit)`. Zero is a multiple of every positive divisor and is represented as `"0"`. A nonpositive limit therefore yields zero. The divisor must be positive and the digit must be from 0 through 9; otherwise return an error.

The implementation omits one boundary value. Return a corrected complete source file in package `solution` with the same exported API.

```go
package solution

import (
	"errors"
	"strconv"
)

func CountDigitInMultiples(limit, divisor, digit int) (int, error) {
	if divisor <= 0 {
		return 0, errors.New("divisor must be positive")
	}
	if digit < 0 || digit > 9 {
		return 0, errors.New("digit must be between zero and nine")
	}
	if limit <= 0 {
		return 0, nil
	}
	target := byte('0' + digit)
	count := 0
	for value := divisor; value < limit; value += divisor {
		text := strconv.Itoa(value)
		for i := 0; i < len(text); i++ {
			if text[i] == target {
				count++
			}
		}
	}
	return count, nil
}
```

